<script lang="ts">
	import UiStatePanel from '$lib/components/UiStatePanel.svelte';
import {getContext} from 'svelte';import {goto} from '$app/navigation';import PageHeader from '#lib/components/PageHeader.svelte';import UiBanner from '#lib/components/UiBanner.svelte';import {createPickingBatchesState} from '../state/pickingBatchesState.svelte';import type {PickingBatch} from '../../domain/entity/PickingBatch';
let {batchId}: {batchId:number} = $props();const vm=createPickingBatchesState();const warehouse=getContext<{warehouseId:number|null}>('warehouseSelection');let target=$state<PickingBatch|null>(null);
$effect(()=>{void vm.loadDetail(warehouse?.warehouseId??null,batchId);});
function date(v:string|null){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?v:d.toLocaleString();}
async function release(){if(!target)return;const result=await vm.release(target);if(result){target=null;await goto('/picking-batches');}}
</script>
<section class="page"><PageHeader title="Detalle del lote" subtitle="Detalle obtenido desde la lista administrativa del almacén seleccionado.">
{#snippet actions()}<button class="secondary" onclick={()=>void goto('/picking-batches')}>Volver</button>{/snippet}
</PageHeader>
{#if vm.detailLoading}<UiStatePanel kind="loading" title="Cargando lote" message="Estamos recuperando el detalle y los pedidos asociados." />{:else if vm.detailError}<UiStatePanel kind="error" title="No se pudo cargar el lote" message={vm.detailError} />{:else if vm.detail}<section class="panel"><header><h2 class="mono">{vm.detail.batchNumber}</h2><span>{vm.detail.status}</span></header><dl><div><dt>Tipo</dt><dd>{vm.detail.kind}</dd></div><div><dt>Picker</dt><dd>{vm.detail.assignedTo??'—'}</dd></div><div><dt>Almacén</dt><dd>{vm.detail.warehouseId}</dd></div><div><dt>Creado</dt><dd>{date(vm.detail.createdAt)}</dd></div><div><dt>Iniciado</dt><dd>{date(vm.detail.startedAt)}</dd></div><div><dt>Progreso</dt><dd>{vm.detail.completedTasks}/{vm.detail.totalTasks}</dd></div><div><dt>Pendientes</dt><dd>{vm.detail.pendingTasks}</dd></div></dl><h3>{vm.detail.kind==='TO'?'Transferencia asociada':'Pedidos asociados'}</h3>{#if vm.detail.kind==='TO'}<p class="mono">{vm.detail.transferOrderNumber??'—'}</p>{:else if vm.detail.orders.length}<ul>{#each vm.detail.orders as so}<li class="mono">{so}</li>{/each}</ul>{:else}<p class="muted">Lote sin pedidos asociados.</p>{/if}{#if vm.detail.kind==='SO'}<button class="danger" onclick={()=>target=vm.detail}>Liberar lote</button>{:else}<p class="muted">Los lotes TO se gestionan desde Órdenes de traslado.</p>{/if}</section>{/if}</section>
{#if target}<div class="backdrop"><div class="modal" role="dialog" aria-modal="true"><h2>¿Liberar {target.batchNumber}?</h2><p>Las reservas se liberarán y las unidades recogidas se restaurarán en el inventario del sistema. La devolución física corresponde al picker.</p>{#if vm.error}<UiBanner tone="error" message={vm.error}/>{/if}<div class="actions"><button class="secondary" onclick={()=>target=null}>Cancelar</button><button class="danger" onclick={()=>void release()} disabled={vm.saving}>{vm.saving?'Liberando…':'Confirmar'}</button></div></div></div>{/if}
<style>
.page{padding:1.25rem;max-width:70rem;margin:auto;color:var(--ink)}.panel{padding:1.25rem;border:1px solid var(--line);border-radius:1rem;background:var(--surface)}header{display:flex;justify-content:space-between;align-items:center}h2{margin:.2rem 0 1rem}.mono{font-family:var(--mono,monospace)}dl{display:grid;grid-template-columns:repeat(auto-fit,minmax(12rem,1fr));gap:.8rem;margin:1.2rem 0}dl div{padding:.75rem;border:1px solid var(--line);border-radius:.65rem}dt{font-size:.72rem;color:var(--slate)}dd{margin:.25rem 0 0;font-weight:650}.muted,.empty{color:var(--slate)}button{border:1px solid var(--navy);background:var(--navy);color:white;border-radius:.55rem;padding:.55rem .85rem;cursor:pointer}.secondary{background:var(--surface);color:var(--ink);border-color:var(--line)}.danger{background:#a52c35;border-color:#a52c35}.backdrop{position:fixed;inset:0;z-index:500;background:#10192388;display:grid;place-items:center;padding:1rem}.modal{width:min(32rem,100%);background:var(--surface);border-radius:1rem;padding:1.25rem}.actions{display:flex;justify-content:flex-end;gap:.6rem;margin-top:1rem}
</style>